fn toggle_case(s: Vec<char>) -> Vec<char> {
    // Requires that the input vector contains valid ASCII characters
    // Ensures that the output vector has the same length as the input vector
    // and that each character is toggled correctly according to the specified rules.
    #[verus]
    requires(s.len() <= 1000); // Example requirement to limit input size for practical verification
    ensures(|result: &Vec<char>| {
        result.len() == s.len() && 
        (0..s.len()).all(|i| {
            let c = s[i];
            let toggled = result[i];
            (c.is_ascii_lowercase() && toggled == (c as u8 - 32) as char) ||
            (c.is_ascii_uppercase() && toggled == (c as u8 + 32) as char) ||
            (!c.is_ascii_lowercase() && !c.is_ascii_uppercase() && toggled == c)
        })
    });
    
    // The invariant ensures that we maintain the properties of the input and output
    let mut result = Vec::with_capacity(s.len());
    for c in s {
        // Each character is processed to toggle its case
        let toggled = if c.is_ascii_lowercase() {
            // Convert lowercase to uppercase
            (c as u8 - 32) as char
        } else if c.is_ascii_uppercase() {
            // Convert uppercase to lowercase
            (c as u8 + 32) as char
        } else {
            // Leave non-alphabetic characters unchanged
            c
        };
        result.push(toggled);
    }
    result
}